#!/usr/bin/env python3
"""IPv6 sparse-node image compiler and lookup command.

Only the Python standard library is used.  The lookup validator reconstructs the
unique image implied by its local rules, which also checks all accounting and
reachability details rather than merely checking their JSON types.
"""

import json
import sys
from fractions import Fraction


class Invalid(Exception):
    pass


def is_int(value):
    return type(value) is int


def require_int(value, lo, hi):
    if not is_int(value) or value < lo or value > hi:
        raise Invalid()
    return value


def exact_keys(obj, keys):
    if type(obj) is not dict or set(obj) != keys:
        raise Invalid()


def align8(x):
    return (x + 7) & ~7


def align64(x):
    return (x + 63) & ~63


def trunc(value, depth):
    if depth == 0:
        return 0
    if depth == 128:
        return value
    shift = 128 - depth
    return (value >> shift) << shift


_HEX = frozenset("0123456789abcdefABCDEF")


def parse_ipv6(text):
    """Parse hexadecimal-only IPv6 notation (not IPv4 dotted notation)."""
    if type(text) is not str or not text:
        raise Invalid()
    if text.count("::") > 1:
        raise Invalid()
    if "::" in text:
        left, right = text.split("::")
        a = left.split(":") if left else []
        b = right.split(":") if right else []
        # A double colon must replace at least one 16-bit group.
        if len(a) + len(b) >= 8:
            raise Invalid()
        groups = a + (["0"] * (8 - len(a) - len(b))) + b
    else:
        groups = text.split(":")
        if len(groups) != 8:
            raise Invalid()
    if len(groups) != 8:
        raise Invalid()
    value = 0
    for group in groups:
        if not (1 <= len(group) <= 4) or any(c not in _HEX for c in group):
            raise Invalid()
        value = (value << 16) | int(group, 16)
    return value


def canonical_ipv6(value):
    groups = [(value >> (112 - 16 * i)) & 0xffff for i in range(8)]
    best_start = -1
    best_length = 0
    i = 0
    while i < 8:
        if groups[i] != 0:
            i += 1
            continue
        j = i + 1
        while j < 8 and groups[j] == 0:
            j += 1
        if j - i > best_length:
            best_start, best_length = i, j - i
        i = j
    if best_length < 2:
        return ":".join(format(g, "x") for g in groups)
    left = ":".join(format(g, "x") for g in groups[:best_start])
    right = ":".join(format(g, "x") for g in groups[best_start + best_length:])
    return left + "::" + right


def canonical_prefix(value, length):
    return canonical_ipv6(value) + "/" + str(length)


def parse_prefix(text, canonical=False):
    if type(text) is not str or text.count("/") != 1:
        raise Invalid()
    address, length_text = text.split("/")
    if (not length_text or
            any(c < "0" or c > "9" for c in length_text) or
            (len(length_text) > 1 and length_text[0] == "0")):
        raise Invalid()
    # More than three digits cannot be in range; avoiding int() also avoids
    # pathological integer conversion on attacker-controlled strings.
    if len(length_text) > 3:
        raise Invalid()
    length = int(length_text)
    if length > 128:
        raise Invalid()
    value = parse_ipv6(address)
    if length < 128 and value & ((1 << (128 - length)) - 1):
        raise Invalid()
    if canonical and text != canonical_prefix(value, length):
        raise Invalid()
    return value, length


def no_duplicate_keys(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise Invalid()
        result[key] = value
    return result


def reject_number(text):
    # No field in either request or image has a non-integer JSON type.
    raise Invalid()


def parse_integer(text):
    if len(text) > 20:
        raise Invalid()
    return int(text)


def preflight(data):
    """Bound parser work on invalid inputs before constructing Python objects.

    The limits are well above what the largest schema-valid request can use.
    In particular, a valid image has at most 1 + 15*2048 nodes and 15*2048
    edges, and its JSON nesting depth is less than twelve.
    """
    if not data:
        raise Invalid()
    depth = 0
    containers = 0
    commas = 0
    in_string = False
    escaped = False
    string_start = 0
    for i, byte in enumerate(data):
        if in_string:
            if escaped:
                escaped = False
            elif byte == 92:       # backslash
                escaped = True
            elif byte == 34:       # quote
                if i - string_start > 4096:
                    raise Invalid()
                in_string = False
            continue
        if byte == 34:
            in_string = True
            string_start = i
        elif byte == 123 or byte == 91:  # { or [
            depth += 1
            containers += 1
            if depth > 16 or containers > 150000:
                raise Invalid()
        elif byte == 125 or byte == 93:  # } or ]
            depth -= 1
            if depth < 0:
                raise Invalid()
        elif byte == 44:            # comma
            commas += 1
            if commas > 400000:
                raise Invalid()
    if in_string or depth != 0:
        raise Invalid()
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        raise Invalid()
    try:
        return json.loads(
            text,
            object_pairs_hook=no_duplicate_keys,
            parse_float=reject_number,
            parse_constant=reject_number,
            parse_int=parse_integer,
        )
    except Invalid:
        raise
    except (ValueError, TypeError, RecursionError, MemoryError) as exc:
        raise Invalid() from exc


def read_fib(records):
    if type(records) is not list or len(records) > 2048:
        raise Invalid()
    answer = []
    seen = set()
    for record in records:
        exact_keys(record, {"prefix", "hop"})
        value, length = parse_prefix(record["prefix"])
        hop = require_int(record["hop"], 0, 65535)
        key = (value, length)
        if key in seen:
            raise Invalid()
        seen.add(key)
        answer.append((value, length, hop))
    return answer


def read_capacities(capacities):
    if type(capacities) is not list or not (4 <= len(capacities) <= 16):
        raise Invalid()
    for capacity in capacities:
        require_int(capacity, 1, 10**9)
    return capacities


class Model:
    """The FIB-derived information shared by cost DP and image generation."""

    def __init__(self, fib):
        self.rules_by_length = [[] for _ in range(129)]
        network_sets = [set() for _ in range(129)]
        network_sets[0].add(0)  # The root exists even for an empty FIB.
        for value, length, hop in fib:
            self.rules_by_length[length].append((value, hop))
            for depth in range(1, length):
                network_sets[depth].add(trunc(value, depth))
        for rules in self.rules_by_length:
            rules.sort(key=lambda item: item[0])
        self.networks = [sorted(networks) for networks in network_sets]

    def cost_table(self, max_stride):
        """Return U(b,e) for every allowed nonempty stage interval.

        At a fixed b, rule costs accumulate as e advances.  Edge sets change
        at every e, so their previous contribution is removed before the new
        one is added.  Only touched nodes need realignment.
        """
        costs = [[None] * 129 for _ in range(129)]
        for b in range(128):
            nodes = self.networks[b]
            m = len(nodes)
            end_limit = min(128, b + max_stride)
            if m == 0:
                for e in range(b + 1, end_limit + 1):
                    costs[b][e] = 0
                continue
            indices = {network: j for j, network in enumerate(nodes)}
            raw = [128] * m
            if b == 0 and self.rules_by_length[0]:
                raw[0] += 32
            aligned = [align64(x) for x in raw]
            total = sum(aligned)
            previous_edges = []
            for e in range(b + 1, end_limit + 1):
                touched = set()
                if previous_edges:
                    old_weight = 32 + align8(e - 1 - b)
                    for j, count in previous_edges:
                        raw[j] -= count * old_weight
                        touched.add(j)
                rule_weight = 32 + align8(e - b)
                for value, _hop in self.rules_by_length[e]:
                    j = indices[trunc(value, b)]
                    raw[j] += rule_weight
                    touched.add(j)
                current_edges = {}
                if e < 128:
                    edge_weight = 32 + align8(e - b)
                    for network in self.networks[e]:
                        j = indices[trunc(network, b)]
                        current_edges[j] = current_edges.get(j, 0) + 1
                    for j, count in current_edges.items():
                        raw[j] += count * edge_weight
                        touched.add(j)
                for j in touched:
                    new_cost = align64(raw[j])
                    total += new_cost - aligned[j]
                    aligned[j] = new_cost
                costs[b][e] = total
                previous_edges = list(current_edges.items())
        return costs

    def build(self, cuts):
        stages = []
        used_bits = []
        for stage_index, (b, e) in enumerate(zip(cuts, cuts[1:])):
            nodes = self.networks[b]
            indices = {network: j for j, network in enumerate(nodes)}
            rule_lists = [[] for _ in nodes]
            rule_extras = [0] * len(nodes)
            if b == 0:
                for value, hop in self.rules_by_length[0]:
                    rule_lists[0].append({"prefix": canonical_prefix(value, 0), "hop": hop})
                    rule_extras[0] += 32
            for length in range(max(1, b + 1), e + 1):
                weight = 32 + align8(length - b)
                for value, hop in self.rules_by_length[length]:
                    j = indices[trunc(value, b)]
                    rule_lists[j].append({
                        "prefix": canonical_prefix(value, length), "hop": hop
                    })
                    rule_extras[j] += weight
            edge_lists = [[] for _ in nodes]
            if e < 128:
                child_indices = {network: j for j, network in enumerate(self.networks[e])}
                for network in self.networks[e]:
                    j = indices[trunc(network, b)]
                    edge_lists[j].append({
                        "prefix": canonical_prefix(network, e),
                        "child": child_indices[network],
                    })
            edge_extra = 0 if e == 128 else 32 + align8(e - b)
            output_nodes = []
            usage = 0
            for j, network in enumerate(nodes):
                cost = align64(128 + rule_extras[j] + len(edge_lists[j]) * edge_extra)
                usage += cost
                output_nodes.append({
                    "prefix": canonical_prefix(network, b),
                    "rules": rule_lists[j],
                    "edges": edge_lists[j],
                })
            stages.append({"nodes": output_nodes})
            used_bits.append(usage)
        return stages, used_bits


def make_image(capacities, max_stride, cuts, stages, used_bits):
    peak = Fraction(0, 1)
    for used, capacity in zip(used_bits, capacities):
        utilization = Fraction(used, capacity)
        if utilization > peak:
            peak = utilization
    return {
        "status": "ok",
        "capacities": capacities,
        "max_stride": max_stride,
        "cuts": cuts,
        "stages": stages,
        "used_bits": used_bits,
        "peak": {"num": peak.numerator, "den": peak.denominator},
    }


def compile_request(request):
    exact_keys(request, {"op", "fib", "capacities", "max_stride"})
    fib = read_fib(request["fib"])
    capacities = read_capacities(request["capacities"])
    max_stride = require_int(request["max_stride"], 1, 32)
    model = Model(fib)
    costs = model.cost_table(max_stride)
    stage_count = len(capacities)

    # next_opt[e] is the exact optimal peak for the already optimized suffix
    # beginning at cut depth e.  Only the base suffix has a state at depth 128.
    next_opt = [None] * 129
    next_opt[128] = Fraction(0, 1)
    choices = [None] * stage_count
    for stage in range(stage_count - 1, -1, -1):
        current_opt = [None] * 129
        current_choice = {}
        capacity = capacities[stage]
        for b in range(128):
            best = None
            best_e = None
            for e in range(b + 1, min(128, b + max_stride) + 1):
                suffix = next_opt[e]
                if suffix is None:
                    continue
                used = costs[b][e]
                if used > capacity:
                    continue
                here = Fraction(used, capacity)
                candidate = here if here > suffix else suffix
                if best is None or candidate < best:
                    best = candidate
                    best_e = e
            if best is not None:
                current_opt[b] = best
                current_choice[b] = best_e
        choices[stage] = current_choice
        next_opt = current_opt
    if next_opt[0] is None:
        return {"status": "infeasible"}
    cuts = [0]
    b = 0
    for stage in range(stage_count):
        b = choices[stage][b]
        cuts.append(b)
    stages, used_bits = model.build(cuts)
    return make_image(capacities, max_stride, cuts, stages, used_bits)


def validate_image(image):
    exact_keys(image, {"status", "capacities", "max_stride", "cuts",
                       "stages", "used_bits", "peak"})
    if image["status"] != "ok" or type(image["status"]) is not str:
        raise Invalid()
    capacities = read_capacities(image["capacities"])
    max_stride = require_int(image["max_stride"], 1, 32)
    stage_count = len(capacities)
    cuts = image["cuts"]
    if type(cuts) is not list or len(cuts) != stage_count + 1:
        raise Invalid()
    for depth in cuts:
        require_int(depth, 0, 128)
    if cuts[0] != 0 or cuts[-1] != 128:
        raise Invalid()
    for b, e in zip(cuts, cuts[1:]):
        if e <= b or e - b > max_stride:
            raise Invalid()
    used_bits = image["used_bits"]
    if type(used_bits) is not list or len(used_bits) != stage_count:
        raise Invalid()
    for used in used_bits:
        require_int(used, 0, 10**20)
    exact_keys(image["peak"], {"num", "den"})
    require_int(image["peak"]["num"], 0, 10**20)
    require_int(image["peak"]["den"], 1, 10**20)

    stages = image["stages"]
    if type(stages) is not list or len(stages) != stage_count:
        raise Invalid()
    fib = []
    seen = set()
    node_count = 0
    edge_count = 0
    for stage in stages:
        exact_keys(stage, {"nodes"})
        nodes = stage["nodes"]
        if type(nodes) is not list or len(nodes) > 2048:
            raise Invalid()
        node_count += len(nodes)
        if node_count > 1 + 15 * 2048:
            raise Invalid()
        for node in nodes:
            exact_keys(node, {"prefix", "rules", "edges"})
            if type(node["prefix"]) is not str:
                raise Invalid()
            rules = node["rules"]
            edges = node["edges"]
            if type(rules) is not list or type(edges) is not list:
                raise Invalid()
            if len(fib) + len(rules) > 2048:
                raise Invalid()
            edge_count += len(edges)
            if edge_count > 15 * 2048:
                raise Invalid()
            for rule in rules:
                exact_keys(rule, {"prefix", "hop"})
                value, length = parse_prefix(rule["prefix"], canonical=True)
                hop = require_int(rule["hop"], 0, 65535)
                key = (value, length)
                if key in seen:
                    raise Invalid()
                seen.add(key)
                fib.append((value, length, hop))
            for edge in edges:
                exact_keys(edge, {"prefix", "child"})
                if type(edge["prefix"]) is not str or not is_int(edge["child"]):
                    raise Invalid()
    model = Model(fib)
    expected_stages, expected_used = model.build(cuts)
    if any(used > capacity for used, capacity in zip(expected_used, capacities)):
        raise Invalid()
    expected = make_image(capacities, max_stride, cuts, expected_stages, expected_used)
    if expected != image:
        raise Invalid()
    return fib


def lookup_request(request):
    exact_keys(request, {"op", "image", "addresses"})
    fib = validate_image(request["image"])
    addresses = request["addresses"]
    if type(addresses) is not list or len(addresses) > 20000:
        raise Invalid()
    by_length = [dict() for _ in range(129)]
    for value, length, hop in fib:
        by_length[length][value] = hop
    active_lengths = [length for length in range(129) if by_length[length]]
    parsed_addresses = [parse_ipv6(address) for address in addresses]
    answers = []
    for address in parsed_addresses:
        best_hop = None
        best_length = None
        for length in active_lengths:
            hop = by_length[length].get(trunc(address, length))
            if hop is not None:
                best_hop = hop
                best_length = length
        answers.append({"hop": best_hop, "prefix_length": best_length})
    return {"status": "ok", "answers": answers}


def handle(request):
    if type(request) is not dict or "op" not in request:
        raise Invalid()
    if request["op"] == "compile":
        return compile_request(request)
    if request["op"] == "lookup":
        return lookup_request(request)
    raise Invalid()


def main():
    output = sys.stdout
    for raw_line in sys.stdin.buffer:
        if raw_line.endswith(b"\n"):
            raw_line = raw_line[:-1]
        try:
            request = preflight(raw_line)
            response = handle(request)
        except Exception:
            # Malformed requests, including resource-hostile JSON, must not
            # poison the next request.  No valid execution path raises here.
            response = {"status": "invalid"}
        output.write(json.dumps(response, separators=(",", ":"), ensure_ascii=True))
        output.write("\n")
        output.flush()


if __name__ == "__main__":
    main()
